package com.servicedesk360.entity;
import jakarta.persistence.*;
@Entity @Table(name="sla_policies",uniqueConstraints=@UniqueConstraint(name="uk_sla_tenant_priority",columnNames={"tenant_id","priority"}))
public class SlaPolicy{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="tenant_id",nullable=false) Long tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) TicketPriority priority; @Column(name="first_response_minutes",nullable=false) Integer firstResponseMinutes; @Column(name="resolution_minutes",nullable=false) Integer resolutionMinutes; @Column(nullable=false) boolean active=true; protected SlaPolicy(){} public SlaPolicy(Long t,TicketPriority p,Integer f,Integer r){tenantId=t;priority=p;firstResponseMinutes=f;resolutionMinutes=r;} public Long getId(){return id;} public Long getTenantId(){return tenantId;} public TicketPriority getPriority(){return priority;} public Integer getFirstResponseMinutes(){return firstResponseMinutes;} public Integer getResolutionMinutes(){return resolutionMinutes;} public boolean isActive(){return active;} public void setFirstResponseMinutes(Integer v){firstResponseMinutes=v;} public void setResolutionMinutes(Integer v){resolutionMinutes=v;} public void setActive(boolean v){active=v;} }
